@pytest.mark.django_db
def test_unbound_form_with_instance():
    form = get_form()
    assert 'value="r" selected' in str(form["color"])

@pytest.mark.django_db
def test_bound_form_with_instance():
    form = get_form(data={"color": "g"})
    assert 'value="g" selected' in str(form["color"])

@pytest.mark.django_db
def test_bound_form_with_instance_empty():
    form = get_form(data={"color": None})
    assert 'value="" selected' in str(form["color"])

@pytest.mark.django_db
def test_fields_value_is_enum_when_unsaved():
    obj = MyModel(color='r')
    assert Color.RED == obj.color

@pytest.mark.django_db
def test_fields_value_is_enum_when_saved():
    obj = MyModel(color='r')
    obj.save()
    assert Color.RED == obj.color

@pytest.mark.django_db
def test_fields_value_is_enum_when_created():
    obj = MyModel.objects.create(color='r')
    assert Color.RED == obj.color

@pytest.mark.django_db
def test_fields_value_is_enum_when_retrieved():
    MyModel.objects.create(color='r')
    obj = MyModel.objects.all()[:1][0]  # .first() not available on all Djangoes
    assert Color.RED == obj.color

@pytest.mark.django_db
def test_nonunique_label():
    obj = MyModel.objects.create(
        color=Color.BLUE,
        labeled_enum=LabeledEnum.FOOBAR
    )
    assert obj.labeled_enum is LabeledEnum.FOOBAR

    obj = MyModel.objects.get(pk=obj.pk)
    assert obj.labeled_enum is LabeledEnum.FOOBAR

def test_choice_ordering():
    EXPECTED_CHOICES = (
        ('r', 'Reddish'),
        ('g', 'Green'),
        ('b', 'bluë'),
    )
    for ((ex_key, ex_val), (key, val)) in zip(EXPECTED_CHOICES, Color.choices()):
        assert key == ex_key
        assert str(val) == str(ex_val)

def test_formfield_labels():
    # Formfield choice label
    form_field = EnumField(Color).formfield()
    expectations = {val.value: str(val) for val in Color}
    for value, text in form_field.choices:
        if value:
            assert text == expectations[value]

def test_formfield_functionality():
    form_cls = type("FauxForm", (BaseForm,), {
        "base_fields": {"color": EnumField(Color).formfield()}
    })
    form = form_cls(data={"color": "r"})
    assert not form.errors
    assert form.cleaned_data["color"] == Color.RED

@pytest.mark.django_db
@pytest.mark.urls('tests.urls')
@pytest.mark.parametrize('q_color', (None, Color.BLUE, Color.RED))
@pytest.mark.parametrize('q_taste', (None, Taste.SWEET, Taste.SOUR))
@pytest.mark.parametrize('q_int_enum', (None, IntegerEnum.A, IntegerEnum.B))
def test_model_admin_filter(admin_client, q_color, q_taste, q_int_enum):
    """
    Test that various combinations of Enum filters seem to do the right thing in the change list.
    """

    # Create a bunch of objects...
    MyModel.objects.create(color=Color.RED)
    for taste in Taste:
        MyModel.objects.create(color=Color.BLUE, taste=taste)
    MyModel.objects.create(color=Color.BLUE, taste=Taste.UMAMI, int_enum=IntegerEnum.A)
    MyModel.objects.create(color=Color.GREEN, int_enum=IntegerEnum.B)

    # Build a Django lookup...
    lookup = {k: v for (k, v) in {
        'color': q_color,
        'taste': q_taste,
        'int_enum': q_int_enum,
    }.items() if v is not None}
    # Build the query string (this is assuming things, sort of)
    qs = {'%s__exact' % k: v.value for (k, v) in lookup.items()}
    # Run the request!
    response = admin_client.get(reverse('admin:tests_mymodel_changelist'), data=qs)
    response.render()

    # Look for the paginator line that lists how many results we found...
    count = int(re.search(r'(\d+) my model', response.content.decode('utf8')).group(1))
    # and compare it to what we expect.
    assert count == MyModel.objects.filter(**lookup).count()

def test_django_admin_lookup_value_for_integer_enum_field():
    field = EnumIntegerField(Taste)

    assert field.get_prep_value(str(Taste.BITTER)) == 3, "get_prep_value should be able to convert from strings"

@pytest.mark.parametrize('instance, representation', [
    ('', ''),
    (None, None),
    ('r', 'r'),
    ('g', 'g'),
    ('b', 'b'),
])
def test_enumfield_to_representation(instance, representation):
    assert EnumField(Color).to_representation(instance) == representation

def test_invalid_enumfield_to_representation():
    with pytest.raises(ValueError, match=r"Invalid value.*"):
        assert EnumField(Color).to_representation('INVALID_ENUM_STRING')

def test_shortness_check():
    class TestModel(models.Model):
        f = EnumField(LabeledEnum, max_length=3, blank=True, null=True)
        f2 = EnumField(LabeledEnum, blank=True, null=True)
    assert any([m.id == 'enumfields.max_length_fit' for m in TestModel.check()])
